// An INSTALLED framework, vendored so the fixture is self-contained while
// still arranging its types the way a real one does: declared in a dependency,
// not in the scanned repo's own source. That origin is what tells a reader
// apart a transport type from a payload type of the user's own, so a fixture
// that declares its framework locally is not arranged like production.
//
// The send here returns a wrapper carrying the payload as a type argument
// rather than the bare platform `Response`.

export interface RequestReader {
  param(name: string): string;
  json<T>(): Promise<T>;
}

export interface TypedResponse<T> extends Response {
  readonly _payload: T;
  readonly _format: 'json';
}

export interface TypedContext {
  req: RequestReader;
  json<T>(body: T, status?: number): TypedResponse<T>;
}

export type TypedHandler = (
  ctx: TypedContext,
) => Promise<TypedResponse<unknown>> | TypedResponse<unknown>;

export declare class TypedRouter {
  get(path: string, ...handlers: TypedHandler[]): this;
  post(path: string, ...handlers: TypedHandler[]): this;
}
